#!/usr/bin/env python3
"""
generate_wrapper.py
Aaroneous Auto-Wrapping Synthesizer:
Generates a complete Machine-Native Linking Protocol (MNLP) Rust wrapper harness for any target CLI or dynamic library.
"""

import os
import sys
import argparse

RUST_WRAPPER_TEMPLATE = """//! Auto-generated Aaroneous Machine-Native Wrapper for: {target_name}
//! Generated by the Aaroneous Stem Cell Auto-Wrapper Engine.

use anyhow::{{Context, Result}};
use tokio::process::Command;
use tracing::{{info, error, warn}};
use std::process::Stdio;

/// Wrapper configuration for {target_name}
#[derive(Debug, Clone)]
pub struct {struct_name}Wrapper {{
    pub executable_path: String,
    pub nats_topic: String,
    pub is_dry_run: bool,
}}

impl Default for {struct_name}Wrapper {{
    fn default() -> Self {{
        Self {{
            executable_path: "{target_path}".to_string(),
            nats_topic: "aaroneous.v1.utility.{target_slug}".to_string(),
            is_dry_run: false,
        }}
    }}
}}

impl {struct_name}Wrapper {{
    pub fn new(executable_path: &str) -> Self {{
        Self {{
            executable_path: executable_path.to_string(),
            ..Default::default()
        }}
    }}

    /// Execute the underlying target tool with arguments and capture machine-native outputs
    pub async fn invoke(&self, args: &[&str], input_payload: Option<&[u8]>) -> Result<Vec<u8>> {{
        info!(target: "{target_slug}_wrapper", ?args, "Invoking target executable");

        if self.is_dry_run {{
            info!(target: "{target_slug}_wrapper", "Dry-run mode active; skipping execution");
            return Ok(b"DRY_RUN_SUCCESS".to_vec());
        }}

        let mut child = Command::new(&self.executable_path)
            .args(args)
            .stdin(if input_payload.is_some() {{ Stdio::piped() }} else {{ Stdio::null() }})
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .with_context(|| format!("Failed to spawn {{}}", self.executable_path))?;

        if let Some(payload) = input_payload {{
            if let Some(mut stdin) = child.stdin.take() {{
                use tokio::io::AsyncWriteExt;
                stdin.write_all(payload).await?;
            }}
        }}

        let output = child.wait_with_output().await?;

        if !output.status.success() {{
            let err_msg = String::from_utf8_lossy(&output.stderr);
            warn!(target: "{target_slug}_wrapper", exit_code = ?output.status.code(), %err_msg, "Target execution reported errors");
        }}

        Ok(output.stdout)
    }}
}}

#[cfg(test)]
mod tests {{
    use super::*;

    #[tokio::test]
    async fn test_wrapper_dry_run() {{
        let mut wrapper = {struct_name}Wrapper::default();
        wrapper.is_dry_run = true;
        let result = wrapper.invoke(&["--version"], None).await;
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), b"DRY_RUN_SUCCESS");
    }}
}}
"""

def generate_wrapper(name: str, target_path: str, output_dir: str):
    struct_name = "".join(part.capitalize() for part in name.replace("-", "_").split("_"))
    target_slug = name.lower().replace(" ", "_").replace("-", "_")

    os.makedirs(output_dir, exist_ok=True)
    out_file = os.path.join(output_dir, f"{target_slug}_wrapper.rs")

    content = RUST_WRAPPER_TEMPLATE.format(
        target_name=name,
        struct_name=struct_name,
        target_path=target_path.replace("\\", "\\\\"),
        target_slug=target_slug
    )

    with open(out_file, "w", encoding="utf-8") as f:
        f.write(content)

    print(f"[+] Successfully synthesized native wrapper harness: {out_file}")
    print(f"    - Struct: {struct_name}Wrapper")
    print(f"    - NATS Topic: aaroneous.v1.utility.{target_slug}")

def main():
    parser = argparse.ArgumentParser(description="Aaroneous Auto-Wrapper Synthesizer")
    parser.add_argument("--name", required=True, help="Target tool name (e.g. ripgrep, ffmpeg, git)")
    parser.add_argument("--path", required=True, help="Path to executable or DLL")
    parser.add_argument("--out", default="d:\\Aaroneous\\dev\\tools\\auto_wrapper\\generated", help="Output directory")

    args = parser.parse_args()
    generate_wrapper(args.name, args.path, args.out)

if __name__ == "__main__":
    main()
